use agmp_native_protocol::{JobSnapshot,JobStartRequest,OutputChunk};use anyhow::{Context,Result};use std::{collections::HashMap,io::{BufRead,BufReader},path::PathBuf,process::{Command,Stdio},sync::{Arc,Mutex},thread,time::{SystemTime,UNIX_EPOCH}};use uuid::Uuid;use crate::sandbox::resolve;
#[derive(Clone)]pub struct JobManager{root:PathBuf,jobs:Arc<Mutex<HashMap<String,Job>>>}#[derive(Clone)]struct Job{snapshot:JobSnapshot,chunks:Arc<Mutex<Vec<OutputChunk>>>}
impl JobManager{pub fn new(root:PathBuf)->Self{Self{root,jobs:Arc::new(Mutex::new(HashMap::new()))}}pub fn start(&self,r:JobStartRequest)->Result<JobSnapshot>{let cwd=r.cwd.as_deref().unwrap_or(".");let cwd=resolve(&self.root,cwd,true)?;let mut cmd=Command::new(&r.executable);cmd.args(&r.arguments).current_dir(&cwd).stdout(Stdio::piped()).stderr(Stdio::piped()).stdin(Stdio::null());let mut child=cmd.spawn().with_context(||format!("start {}",r.executable))?;let id=format!("JOB-{}",Uuid::new_v4());let snapshot=JobSnapshot{id:id.clone(),state:"running".into(),pid:child.id(),exit_code:None,cwd:cwd.to_string_lossy().into_owned(),created_at:now()};let chunks=Arc::new(Mutex::new(Vec::new()));let max=r.max_output_bytes.max(1024).min(4_194_304);if let Some(stdout)=child.stdout.take(){spawn_reader(chunks.clone(),"stdout",stdout,max)}if let Some(stderr)=child.stderr.take(){spawn_reader(chunks.clone(),"stderr",stderr,max)}self.jobs.lock().unwrap().insert(id.clone(),Job{snapshot:snapshot.clone(),chunks:chunks.clone()});let jobs=self.jobs.clone();thread::spawn(move||{if let Ok(status)=child.wait(){if let Some(job)=jobs.lock().unwrap().get_mut(&id){job.snapshot.exit_code=status.code();job.snapshot.state=if status.success(){"succeeded".into()}else{"failed".into()}}}});Ok(snapshot)}pub fn get(&self,id:&str)->Result<JobSnapshot>{self.jobs.lock().unwrap().get(id).map(|j|j.snapshot.clone()).ok_or_else(||anyhow::anyhow!("job not found"))}pub fn output(&self,id:&str,after:u64,limit:usize)->Result<serde_json::Value>{let jobs=self.jobs.lock().unwrap();let job=jobs.get(id).ok_or_else(||anyhow::anyhow!("job not found"))?;let chunks=job.chunks.lock().unwrap();let out=chunks.iter().filter(|x|x.sequence>after).take(limit.clamp(1,500)).cloned().collect::<Vec<_>>();let next=out.last().map(|x|x.sequence).unwrap_or(after);Ok(serde_json::json!({"id":id,"chunks":out,"nextCursor":next,"truncated":false}))}}
fn spawn_reader<R:std::io::Read+Send+'static>(chunks:Arc<Mutex<Vec<OutputChunk>>>,stream:&'static str,reader:R,max:usize){thread::spawn(move||{let mut total=0usize;for line in BufReader::new(reader).lines().map_while(Result::ok){let text=format!("{}\n",line);total+=text.len();if total>max{break}let mut all=chunks.lock().unwrap();let seq=all.last().map(|x|x.sequence+1).unwrap_or(1);all.push(OutputChunk{sequence:seq,stream:stream.into(),text});if all.len()>2000{all.drain(0..1000);}}});}fn now()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis() as u64}
